// Segment Tree — O(n) build, O(log n) query and update
class SegmentTree {
  #n;
  #tree;

  constructor(arr) {
    this.#n    = arr.length;
    this.#tree = new Array(4 * this.#n).fill(0);
    this.#build(arr, 1, 0, this.#n - 1);
  }

  #build(arr, node, start, end) {
    if (start === end) {
      this.#tree[node] = arr[start];
    } else {
      const mid = (start + end) >> 1;
      this.#build(arr, 2*node,   start, mid);
      this.#build(arr, 2*node+1, mid+1, end);
      this.#tree[node] = this.#tree[2*node] + this.#tree[2*node+1];
    }
  }

  // O(log n) — point update: set index i to val
  update(i, val, node=1, start=0, end=this.#n-1) {
    if (start === end) {
      this.#tree[node] = val;
    } else {
      const mid = (start + end) >> 1;
      if (i <= mid) this.update(i, val, 2*node,   start, mid);
      else          this.update(i, val, 2*node+1, mid+1, end);
      this.#tree[node] = this.#tree[2*node] + this.#tree[2*node+1];
    }
  }

  // O(log n) — range sum query [l..r]
  query(l, r, node=1, start=0, end=this.#n-1) {
    if (r < start || end < l) return 0;             // outside range
    if (l <= start && end <= r) return this.#tree[node]; // inside range
    const mid = (start + end) >> 1;
    return this.query(l, r, 2*node,   start, mid)
         + this.query(l, r, 2*node+1, mid+1, end);
  }
}

// Fenwick Tree (BIT) — O(n) build, O(log n) prefix sum and update
class FenwickTree {
  #bit;
  constructor(n) { this.#bit = new Array(n + 1).fill(0); }

  // O(log n) — add delta to index i (1-indexed)
  update(i, delta) {
    for (; i < this.#bit.length; i += i & (-i))
      this.#bit[i] += delta;
  }

  // O(log n) — prefix sum [1..i]
  query(i) {
    let sum = 0;
    for (; i > 0; i -= i & (-i)) sum += this.#bit[i];
    return sum;
  }

  // O(log n) — range sum [l..r] (1-indexed)
  rangeQuery(l, r) { return this.query(r) - this.query(l - 1); }
}

const arr = [1, 2, 3, 4, 4, 5, 7, 10];
const seg = new SegmentTree(arr);
console.log(seg.query(2, 5));  // 3+4+4+5 = 16
seg.update(3, 10);             // change index 3 from 4 to 10
console.log(seg.query(2, 5));  // 3+10+4+5 = 22

const bit = new FenwickTree(8);
arr.forEach((v, i) => bit.update(i + 1, v)); // 1-indexed
console.log(bit.rangeQuery(3, 6));             // 3+4+4+5 = 16
bit.update(4, 6);                              // add 6 to index 4 (now 10)
console.log(bit.rangeQuery(3, 6));             // 3+10+4+5 = 22

// Segment tree for RANGE MINIMUM QUERY (RMQ) — O(log n)
class RMQTree {
  #n; #tree;
  constructor(arr) {
    this.#n    = arr.length;
    this.#tree = new Array(4 * this.#n).fill(Infinity);
    this.#build(arr, 1, 0, this.#n - 1);
  }
  #build(arr, node, s, e) {
    if (s === e) { this.#tree[node] = arr[s]; return; }
    const m = (s + e) >> 1;
    this.#build(arr, 2*node,   s, m);
    this.#build(arr, 2*node+1, m+1, e);
    this.#tree[node] = Math.min(this.#tree[2*node], this.#tree[2*node+1]);
  }
  query(l, r, node=1, s=0, e=this.#n-1) {
    if (r < s || e < l) return Infinity;
    if (l <= s && e <= r) return this.#tree[node];
    const m = (s + e) >> 1;
    return Math.min(
      this.query(l, r, 2*node,   s, m),
      this.query(l, r, 2*node+1, m+1, e)
    );
  }
}

// Complexity comparison for range operations on array of size n
//
// Approach          | Build  | Query | Update | Space
// Brute force       | O(1)   | O(n)  | O(1)   | O(n)
// Prefix sums       | O(n)   | O(1)  | O(n)   | O(n)   ← no updates
// Segment tree      | O(n)   | O(logn)| O(logn)| O(n)
// Fenwick tree      | O(n)   | O(logn)| O(logn)| O(n)   ← prefix only
// Sparse table      | O(n logn)| O(1) | N/A    | O(n logn) ← static RMQ

const rmq = new RMQTree([3, 1, 4, 1, 5, 9, 2, 6]);
console.log(rmq.query(1, 5)); // min(1,4,1,5,9) = 1
console.log(rmq.query(4, 7)); // min(5,9,2,6)   = 2
